-- First contact is no longer recorded explicitly; the routing SLA counts logged activity instead.
CREATE OR REPLACE VIEW platform.routing_sla_companies WITH(security_barrier=true) AS SELECT DISTINCT c.id AS company_id FROM platform.companies c JOIN tenant.leads l ON l.company_id=c.id JOIN tenant.routing_rules r ON r.company_id=l.company_id AND r.id=l.routing_rule_id WHERE c.status IN ('pending','trial','active') AND NOT EXISTS(SELECT 1 FROM tenant.lead_activities ca WHERE ca.company_id=l.company_id AND ca.lead_id=l.id AND ca.actor_id IS NOT NULL AND ca.kind IN ('lead.note_added','lead.call_logged','lead.whatsapp_logged','lead.email_logged','lead.viewing_logged') AND ca.created_at>=coalesce(l.assigned_at,l.created_at)) AND l.archived_at IS NULL AND l.stage NOT IN ('won','lost','unqualified') AND l.routing_attempts<3 AND r.active AND r.archived_at IS NULL AND r.sla_minutes>0 AND l.assigned_at+make_interval(mins=>r.sla_minutes)<=now() AND EXISTS(SELECT 1 FROM platform.subscriptions s WHERE s.company_id=c.id AND s.status IN ('active','trialing') AND s.period_end>now());
DROP INDEX IF EXISTS tenant.leads_routing_sla;
ALTER TABLE tenant.leads DROP COLUMN first_contact_at;
CREATE INDEX leads_routing_sla ON tenant.leads(company_id,routing_rule_id,assigned_at) WHERE archived_at IS NULL;
